defmodule MedicaidClaimsChecker.X12.ClaimSplitterTest do
  use ExUnit.Case, async: true

  alias MedicaidClaimsChecker.X12.{ClaimSplitter, Converter, SegmentMapper}

  # Raw X12 files from mock_data/ (generated by mock_data/generate.exs).

  defp read(rel), do: MedicaidClaimsChecker.MockData.read!(rel)

  # The upload/fetch path: transaction sets, then claims, then conversion.
  defp claims(content) do
    with {:ok, sets} <- ClaimSplitter.split_transaction_sets(content) do
      (sets || [content])
      |> Enum.flat_map(fn set ->
        case ClaimSplitter.split_claims_to_x12(set) do
          {:ok, nil} -> [set]
          {:ok, parts} -> Enum.map(parts, & &1.x12_content)
        end
      end)
      |> Enum.map(fn x12 ->
        {:ok, flat} = Converter.convert_content(x12)
        {:ok, claim} = SegmentMapper.map_from_json(flat)
        claim
      end)
      |> then(&{:ok, &1})
    end
  end

  describe "check_envelope via split_transaction_sets/1" do
    test "accepts a well-formed file" do
      assert {:ok, nil} =
               ClaimSplitter.split_transaction_sets(
                 read("x12_files/837p_professional/clean_office_visit.x12")
               )
    end

    test "rejects a truncated file as an incomplete transmission" do
      assert {:error, "Incomplete transmission:" <> _} =
               ClaimSplitter.split_transaction_sets(
                 read("x12_files/broken_envelope_or_file/truncated.x12")
               )
    end

    test "rejects a wrong SE segment count" do
      assert {:error, "SE segment count is 27 but transaction set 0001 has 24 segments"} =
               ClaimSplitter.split_transaction_sets(
                 read("x12_files/broken_envelope_or_file/wrong_se_count.x12")
               )
    end

    test "rejects an IEA control number that differs from ISA13" do
      assert {:error,
              "Interchange control number mismatch: ISA13 is 000000101 but IEA02 is 000000999"} =
               ClaimSplitter.split_transaction_sets(
                 read("x12_files/broken_envelope_or_file/control_number_mismatch.x12")
               )
    end

    test "rejects a GE count that doesn't match the transaction sets" do
      content =
        String.replace(
          read("x12_files/several_transaction_sets/two_transaction_sets.x12"),
          "GE*2*101~",
          "GE*1*101~"
        )

      assert {:error, "GE says 1 transaction sets but the group has 2"} =
               ClaimSplitter.split_transaction_sets(content)
    end

    test "rejects an interchange that opens before the previous one is closed" do
      clean = read("x12_files/837p_professional/clean_office_visit.x12")
      [without_iea, _] = String.split(clean, "IEA*", parts: 2)

      assert {:error, "Incomplete transmission: interchange 000000101 has no IEA trailer"} =
               ClaimSplitter.split_transaction_sets(without_iea <> clean)
    end
  end

  describe "split_transaction_sets/1 with several interchanges" do
    test "a file holding two interchanges gives one standalone piece per transaction set" do
      clean = read("x12_files/837p_professional/clean_office_visit.x12")
      two_sets = read("x12_files/several_transaction_sets/two_transaction_sets.x12")

      {:ok, pieces} = ClaimSplitter.split_transaction_sets(clean <> two_sets)
      assert length(pieces) == 3

      # Each piece is a valid file on its own: one set, one group, one interchange.
      for piece <- pieces do
        assert {:ok, nil} = ClaimSplitter.split_transaction_sets(piece)
      end

      {:ok, from_clean} = claims(clean)
      {:ok, from_two_sets} = claims(two_sets)
      assert {:ok, from_clean ++ from_two_sets} == claims(clean <> two_sets)
    end
  end

  describe "reading the file" do
    test "ignores a byte-order mark and leading blank lines" do
      clean = read("x12_files/837p_professional/clean_office_visit.x12")
      {:ok, [expected]} = claims(clean)

      assert {:ok, [^expected]} = claims(<<0xEF, 0xBB, 0xBF>> <> clean)
      assert {:ok, [^expected]} = claims("\r\n\n  " <> clean)
    end

    test "a one-line file missing only its final terminator still reads" do
      clean = read("x12_files/837p_professional/clean_office_visit.x12")
      {:ok, [expected]} = claims(clean)

      oneline = clean |> String.replace(~r/~\s*/, "~") |> String.trim_trailing("~")
      assert {:ok, [^expected]} = claims(oneline)
    end

    test "a newline can be the segment terminator" do
      clean = read("x12_files/837p_professional/clean_office_visit.x12")
      {:ok, [expected]} = claims(clean)

      assert {:ok, [^expected]} = claims(String.replace(clean, ~r/~\r?\n?/, "\n"))
    end

    test "errors are plain sentences without a wrapper or quotes" do
      assert {:error, "Not an X12 file: it must start with ISA, the interchange header"} =
               ClaimSplitter.split_transaction_sets("HELLO")

      assert {:error, "File too short to hold an ISA interchange header"} =
               ClaimSplitter.split_transaction_sets("ISA*00*~")

      assert {:error, "The ISA interchange header is not the standard fixed width" <> _} =
               ClaimSplitter.split_transaction_sets(
                 String.replace(
                   read("x12_files/837p_professional/clean_office_visit.x12"),
                   "TESTSUBMIT01   ",
                   "TESTSUBMIT01"
                 )
               )
    end
  end

  describe "split_claims_to_x12/1" do
    test "a transaction set with no CLM is an error, not an empty claim" do
      content = read("x12_files/broken_envelope_or_file/envelope_no_claims.x12")
      assert {:error, "No claims found" <> _} = ClaimSplitter.split_claims_to_x12(content)
    end

    test "two claims under one subscriber each keep their own lines" do
      assert {:ok, [first, second]} =
               claims(
                 read(
                   "x12_files/several_claims_one_transaction_set/two_claims_same_subscriber.x12"
                 )
               )

      assert first["claim_id"] == "SAMESUB01"
      assert Enum.map(first["service_lines"], & &1["charge_amount"]) == ["150.00"]
      assert second["claim_id"] == "SAMESUB02"
      assert Enum.map(second["service_lines"], & &1["charge_amount"]) == ["2.00"]

      for claim <- [first, second] do
        assert claim["billing_provider"]["npi"] == "1003001538"
        assert claim["patient"]["date_of_birth"] == "19850315"
      end
    end

    test "claims under different subscribers keep their own subscriber" do
      assert {:ok, claims} =
               claims(read("x12_files/several_claims_one_transaction_set/three_claims.x12"))

      assert Enum.map(claims, &{&1["claim_id"], &1["patient"]["name"]["last"]}) ==
               [{"MULTI01", "ALPHA"}, {"MULTI02", "BRAVO"}, {"MULTI03", "CHARLIE"}]
    end

    test "each claim carries its own billing provider when a file has two" do
      content =
        read("x12_files/several_claims_one_transaction_set/two_claims_same_subscriber.x12")

      # Give the second claim its own billing-provider (HL 20) and subscriber loop.
      [head, tail] = String.split(content, "CLM*SAMESUB02", parts: 2)

      second_provider =
        "HL*3**20*1~\nNM1*85*2*THE ROSS ORTHOPAEDIC WELLNESS CENTER*****XX*1003005000~\n" <>
          "HL*4*3*22*0~\nSBR*P*18*******MC~\nNM1*IL*1*SECOND*PAT****MI*MCD000000999~\n"

      content = head <> second_provider <> "CLM*SAMESUB02" <> tail
      {:ok, parts} = ClaimSplitter.split_claims_to_x12(content)

      npis =
        Enum.map(parts, fn %{x12_content: x12} ->
          {:ok, flat} = Converter.convert_content(x12)
          {:ok, claim} = SegmentMapper.map_from_json(flat)
          {claim["claim_id"], claim["billing_provider"]["npi"], claim["patient"]["name"]["last"]}
        end)

      assert npis == [
               {"SAMESUB01", "1003001538", "TESTPATIENT"},
               {"SAMESUB02", "1003005000", "SECOND"}
             ]
    end

    test "split claims keep the file's own delimiters and a correct SE count" do
      three = read("x12_files/several_claims_one_transaction_set/three_claims.x12")
      piped = String.replace(three, "*", "|")

      {:ok, parts} = ClaimSplitter.split_claims_to_x12(piped)
      assert length(parts) == 3

      for %{x12_content: x12} <- parts do
        refute x12 =~ "*"
        assert {:ok, nil} = ClaimSplitter.split_transaction_sets(x12)
      end

      assert claims(piped) == claims(three)
    end
  end

  describe "conversion details" do
    test "uses the file's sub-element separator (ISA16) for composites" do
      assert {:ok, [claim]} =
               claims(read("edi_files/alternate_delimiters/alternate_delimiters.edi"))

      assert [%{"procedure_code" => "99285", "procedure_qualifier" => "HC"}] =
               claim["service_lines"]

      assert [%{code: "Z0000", qualifier: "ABK"}] = claim["diagnosis_codes"]
      assert claim["claim_details"]["place_of_service"] == "23"
    end

    test "keeps REF*G1 prior authorization" do
      assert {:ok, [claim]} =
               claims(
                 read(
                   "R_business_rules/R2_each_rule_alone/UnauthorizedProcedure_with_auth_no_match.x12"
                 )
               )

      assert claim["authorization"]["authorization_number"] == "PA20260001"

      assert {:ok, [claim]} =
               claims(read("R_business_rules/R2_each_rule_alone/UnauthorizedProcedure.x12"))

      assert claim["authorization"]["authorization_number"] == nil
    end

    test "keeps place of service on the claim and each service line" do
      assert {:ok, [claim]} =
               claims(read("R_business_rules/R6_weekend_office_variants/saturday_office.x12"))

      assert claim["claim_details"]["place_of_service"] == "11"
      assert [%{"place_of_service" => "11"}] = claim["service_lines"]
    end

    test "837I claim-level dates are kept and a line without a date takes the statement period" do
      assert {:ok, [claim]} =
               claims(read("x12_files/837i_institutional/institutional_claim_dates.x12"))

      assert %{
               "statement_from_date" => "20260910",
               "statement_to_date" => "20260912",
               "admission_date" => "20260910"
             } = claim["claim_details"]

      assert [%{"date_of_service" => "20260910", "date_of_service_end" => "20260912"}] =
               claim["service_lines"]
    end

    test "a line date range gives its start as date_of_service and its end separately" do
      assert {:ok, [claim]} = claims(read("x12_files/837p_professional/line_date_range.x12"))

      assert [%{"date_of_service" => "20260901", "date_of_service_end" => "20260903"}] =
               claim["service_lines"]

      # A single date has no end.
      assert {:ok, [plain]} =
               claims(read("x12_files/837p_professional/clean_office_visit.x12"))

      assert [%{"date_of_service" => "20260901", "date_of_service_end" => nil}] =
               plain["service_lines"]
    end

    test "a dependant's own patient loop fills the patient fields" do
      assert {:ok, [claim]} =
               claims(read("x12_files/837p_professional/patient_not_subscriber.x12"))

      assert claim["patient"] == %{
               "date_of_birth" => "20200101",
               "gender" => "M",
               "name" => %{"first" => "KID", "last" => "CHILD", "middle" => nil}
             }

      assert claim["subscriber"][:first_name] == "ALEX"
    end

    test "blank elements become nil everywhere, so IS NULL rules see them" do
      clean = read("x12_files/837i_institutional/institutional.x12")

      blanked =
        clean
        |> String.replace("DMG*D8*19850315*F", "DMG*D8**F")
        |> String.replace("SV2*0450*HC:99284*900.00*UN*1", "SV2*0450**900.00*UN*1")

      assert {:ok, [claim]} = claims(blanked)
      assert claim["patient"]["date_of_birth"] == nil
      assert claim["subscriber"][:date_of_birth] == nil
      assert [%{"procedure_code" => nil, "procedure_qualifier" => nil}] = claim["service_lines"]
      assert claim["patient"]["name"]["middle"] == nil
    end

    test "an absent billing NPI becomes nil, not an empty string" do
      assert {:ok, [claim]} =
               claims(read("N_nppes_provider_checks/N10_no_billing_npi/missing_billing_npi.x12"))

      assert claim["provider"]["npi"] == nil
      assert claim["billing_provider"]["npi"] == nil
    end
  end
end
